<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ConsentPurpose\Domain\Gateway;

use Civi\Lughauth\Features\Access\ConsentPurpose\Domain\ConsentPurpose;

class ConsentPurposeCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(ConsentPurpose $consentPurpose, ?int $size): ConsentPurposeCursor
    {
        $next = clone $this;
        $next->sinceUid = $consentPurpose->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
